local CG = game:GetService("CoreGui")
if CG:FindFirstChild("SavedMacroUI") then CG.SavedMacroUI:Destroy() end
local SG = Instance.new("ScreenGui", CG) SG.Name = "SavedMacroUI"
local F = Instance.new("Frame", SG) F.Size = UDim2.new(0, 200, 0, 190) F.Position = UDim2.new(0.8, 0, 0.5, 0) F.BackgroundColor3 = Color3.fromRGB(15,15,18) F.Draggable = true F.Active = true F.BorderSizePixel = 0 Instance.new("UICorner", F).CornerRadius = UDim.new(0, 8)
local TB = Instance.new("Frame", F) TB.Size = UDim2.new(1, 0, 0, 30) TB.BackgroundColor3 = Color3.fromRGB(22,22,28) Instance.new("UICorner", TB).CornerRadius = UDim.new(0, 8)
local Title = Instance.new("TextLabel", TB) Title.Size = UDim2.new(0.7, 0, 1, 0) Title.Position = UDim2.new(0, 10, 0, 0) Title.Text = "MOUNT LONELY MAX SPEED 3" Title.TextColor3 = Color3.fromRGB(0, 255, 200) Title.BackgroundTransparency = 1 Title.Font = Enum.Font.GothamBold Title.TextSize = 11 Title.TextXAlignment = Enum.TextXAlignment.Left
local BtnMin = Instance.new("TextButton", TB) BtnMin.Size = UDim2.new(0.15, 0, 1, 0) BtnMin.Position = UDim2.new(0.7, 0, 0, 0) BtnMin.Text = "—" BtnMin.TextColor3 = Color3.new(1,1,1) BtnMin.BackgroundTransparency = 1
local BtnClose = Instance.new("TextButton", TB) BtnClose.Size = UDim2.new(0.15, 0, 1, 0) BtnClose.Position = UDim2.new(0.85, 0, 0, 0) BtnClose.Text = "✕" BtnClose.TextColor3 = Color3.fromRGB(255,80,80) BtnClose.BackgroundTransparency = 1
local Cont = Instance.new("Frame", F) Cont.Size = UDim2.new(1, 0, 1, -30) Cont.Position = UDim2.new(0, 0, 0, 30) Cont.BackgroundTransparency = 1
local SpeedInp = Instance.new("TextBox", Cont) SpeedInp.Size = UDim2.new(0.9, 0, 0, 28) SpeedInp.Position = UDim2.new(0.05, 0, 0, 8) SpeedInp.Text = "1" SpeedInp.BackgroundColor3 = Color3.fromRGB(25,25,30) SpeedInp.TextColor3 = Color3.new(1,1,1) SpeedInp.Font = Enum.Font.Gotham Instance.new("UICorner", SpeedInp).CornerRadius = UDim.new(0, 5)
local BtnPlay = Instance.new("TextButton", Cont) BtnPlay.Size = UDim2.new(0.9, 0, 0, 30) BtnPlay.Position = UDim2.new(0.05, 0, 0, 44) BtnPlay.Text = "▶️ PLAY / STOP" BtnPlay.BackgroundColor3 = Color3.fromRGB(40, 140, 70) BtnPlay.TextColor3 = Color3.new(1,1,1) BtnPlay.Font = Enum.Font.GothamSemibold Instance.new("UICorner", BtnPlay).CornerRadius = UDim.new(0, 5)
local BtnLoop = Instance.new("TextButton", Cont) BtnLoop.Size = UDim2.new(0.9, 0, 0, 30) BtnLoop.Position = UDim2.new(0.05, 0, 0, 80) BtnLoop.Text = "🔁 LOOP: OFF" BtnLoop.BackgroundColor3 = Color3.fromRGB(60, 60, 65) BtnLoop.TextColor3 = Color3.new(1,1,1) BtnLoop.Font = Enum.Font.GothamSemibold Instance.new("UICorner", BtnLoop).CornerRadius = UDim.new(0, 5)

local MinC = Instance.new("TextButton", SG) MinC.Size = UDim2.new(0, 40, 0, 40) MinC.BackgroundColor3 = Color3.fromRGB(22, 22, 28) MinC.Text = "AL" MinC.TextColor3 = Color3.fromRGB(0, 255, 200) MinC.Font = Enum.Font.GothamBold MinC.Visible = false MinC.Active = true MinC.Draggable = true Instance.new("UICorner", MinC).CornerRadius = UDim.new(0, 20)
BtnMin.MouseButton1Click:Connect(function() MinC.Position = F.Position F.Visible = false MinC.Visible = true end)
MinC.MouseButton1Click:Connect(function() F.Position = MinC.Position MinC.Visible = false F.Visible = true end)
BtnClose.MouseButton1Click:Connect(function() SG:Destroy() end)

local isPlaying, loopEnabled = false, false
BtnLoop.MouseButton1Click:Connect(function() loopEnabled = not loopEnabled BtnLoop.Text = loopEnabled and "🔁 LOOP: ON" or "🔁 LOOP: OFF" BtnLoop.BackgroundColor3 = loopEnabled and Color3.fromRGB(150, 100, 20) or Color3.fromRGB(60, 60, 65) end)

BtnPlay.MouseButton1Click:Connect(function()
    if isPlaying then isPlaying = false BtnPlay.Text = "▶️ PLAY / STOP" return end
    isPlaying = true BtnPlay.Text = "⏹️ STOP"
    task.spawn(function()
        local RS = game:GetService("RunService")
        while isPlaying do
            local spd = tonumber(SpeedInp.Text) or 1
            local p = game.Players.LocalPlayer local hrp = p.Character.HumanoidRootPart local h = p.Character.Humanoid
            
            hrp.Anchored = false
            h:ChangeState(Enum.HumanoidStateType.Physics)
            
            local magnet = Instance.new("Part") magnet.Anchored = true magnet.CanCollide = false magnet.Transparency = 1 magnet.CFrame = hrp.CFrame magnet.Parent = workspace
            local att1 = Instance.new("Attachment", hrp) local att2 = Instance.new("Attachment", magnet)
            local ap = Instance.new("AlignPosition", hrp) ap.Mode = Enum.PositionAlignmentMode.TwoAttachment ap.Attachment0 = att1 ap.Attachment1 = att2 ap.MaxForce = math.huge ap.Responsiveness = 200
            local ao = Instance.new("AlignOrientation", hrp) ao.Mode = Enum.OrientationAlignmentMode.TwoAttachment ao.Attachment0 = att1 ao.Attachment1 = att2 ao.MaxTorque = math.huge ao.Responsiveness = 200
            
            local i = 1
            while i <= #frames and isPlaying do
                if frames[math.floor(i)] then
                    magnet.CFrame = CFrame.new(unpack(frames[math.floor(i)].c))
                    RS.Heartbeat:Wait()
                end
                i = i + spd
            end
            
            ap:Destroy() ao:Destroy() att1:Destroy() att2:Destroy() magnet:Destroy()
            h:ChangeState(Enum.HumanoidStateType.GettingUp)
            if not loopEnabled or not isPlaying then break end
            task.wait(3)
        end
        isPlaying = false BtnPlay.Text = "▶️ PLAY / STOP"
    end)
end)
